const state={authMode:'login',authError:'',authNotice:'',recovery:false,authBusy:false,creationEdition:(new URLSearchParams(location.search).get('edition')||localStorage.getItem('punch-creation-edition'))==='essential'?'essential':'construction',breaks:[],user:null,account:null,section:'home',sub:'',session:null,segments:[],sessions:[],jobs:[],assignments:[],orders:[],leaves:[],corrections:[],documents:[],receipts:[],localPending:0,serverPunch:{sessions:[],segments:[]},locationChecks:[],notifications:[],shifts:[],acks:[],weeks:[],audit:[],conversations:[],messages:[],chatId:null,teamList:[],members:[],contacts:[],credentials:[],profile:null,archived:[],selected:null,next:null,filter:'all',search:'',position:null,gpsLoading:false,busy:false,error:'',notice:'',toast:null,time:Date.now(),routeMode:'browse',detailId:null,providers:{google:null,apple:null}};
const urls={google:j=>'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(j.latitude!=null&&j.longitude!=null?j.latitude+','+j.longitude:j.address),waze:j=>'https://waze.com/ul?'+(j.latitude!=null&&j.longitude!=null?'ll='+encodeURIComponent(j.latitude+','+j.longitude):'q='+encodeURIComponent(j.address))+'&navigate=yes'};
function toast(t){state.toast=t;const existing=$('toast');if(existing){existing.textContent=t;existing.style.display='block'}setTimeout(()=>{if(state.toast===t){state.toast=null;const n=$('toast');if(n)n.style.display='none'}},3900)}
function error(err){console.error(err);toast(err?.message||String(err)||'Erreur inconnue')}
function when(d){return new Date(d).toLocaleString('fr-CA',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}
function mins(v){const n=Math.floor(Math.max(0,v)/60000);return Math.floor(n/60)+' h '+String(n%60).padStart(2,'0')}
function elapsed(ms){const n=Math.max(0,Math.floor(ms/1000));return [Math.floor(n/3600),Math.floor(n%3600/60),n%60].map(x=>String(x).padStart(2,'0')).join(':')}
function labelRole(r){return({employee:'Employé',lead:"Chef d'équipe",admin:'Administrateur',boss:'Boss'})[r]||r}
function getJob(id){return state.jobs.find(j=>j.id===id)}
function selectedJob(){return getJob(state.selected)||null}
function company(){return state.account?.company_id}
function manager(){return ['boss','admin'].includes(state.account?.role)}
function member(){return !!state.account&&!!state.user}
function $val(id){return $(id)?.value?.trim()||''}
function button(title,action,kind='',extra=''){return '<button type="button" class="btn '+kind+'" data-action="'+e(action)+'" '+extra+'>'+title+'</button>'}
function card(v,style=''){return '<section class="card '+style+'">'+v+'</section>'}
function formfield(label,id,val='',type='text',extra=''){return '<div class="group"><label for="'+id+'">'+label+'</label><input class="field" id="'+id+'" type="'+type+'" value="'+e(val)+'" '+extra+'></div>'}
function heading(title,back){return '<div class="between"><h2>'+title+'</h2>'+(back?button('← Retour',back):'')+'</div>'}
function stateText(s){return ({pending:'En attente',approved:'Approuvé',rejected:'Refusé',requested:'Demandé',ordered:'Commandé',delivered:'Livré',restricted:'Gestion suspendue',grace:'Surcis',setup:'Configuration',active:'Actif'})[s]||s||'—'}
function isRestrict(){return ['restricted','cancelled'].includes(state.account?.companies?.billing_status)}
function authHTML(){const signup=state.authMode==='signup';return '<div class="authwrap"><div class="huge">PUNCH <b>360°</b></div>'+ (state.recovery?'<h2>Nouveau mot de passe</h2><form id="recoveryForm">'+formfield('Nouveau mot de passe','newPassword','','password','autocomplete="new-password" minlength="8" required')+formfield('Confirmer le mot de passe','confirmPassword','','password','autocomplete="new-password" required')+'<button class="btn gold full" type="submit" '+(state.authBusy?'disabled':'')+'>Enregistrer le mot de passe</button></form>':!state.user?'<div class="tag">LE CHANTIER DANS TA POCHE</div><p>Vos heures. Vos équipes. Vos chantiers. Tout au même endroit.</p>'+planCards()+'<h2>'+ (signup?'Créer mon compte':'Bienvenue')+'</h2><p>'+(signup?'Inscription par courriel. Aucun paiement demandé.':'Connecte-toi ou crée ton compte pour commencer.')+'</p><form id="authForm">'+formfield('Adresse courriel','email','','email','autocomplete="email" inputmode="email" required')+formfield('Mot de passe'+(signup?' — 8 caractères minimum':''),'password','','password','autocomplete="'+(signup?'new-password':'current-password')+'" '+(signup?'minlength="8" ':'')+'required')+'<button class="btn gold full" type="submit" '+(state.authBusy?'disabled':'')+'>'+(state.authBusy?'Un instant…':signup?'Créer mon compte':'Se connecter')+'</button></form>'+button(signup?'Déjà inscrit ? Se connecter':'Nouveau ? Créer un compte','authMode','full')+button('Mot de passe oublié','resetPassword')+button('Renvoyer le courriel de confirmation','resendConfirmation')+'<div class="oauth-divider"><span>OU CONTINUER AVEC</span></div><div class="oauth-buttons">'+(['google','apple'].filter(p=>state.providers[p]!==false).map(p=>'<button type="button" class="oauth-btn oauth-'+p+'" data-action="oauth'+(p==='google'?'Google':'Apple')+'">Continuer avec '+(p==='google'?'Google':'Apple')+'</button>').join(''))+'</div>':'<div class="tag">'+e(state.user.email)+'</div><h2>Créer mon espace</h2><p>Choisis ta version, puis donne un nom à ton entreprise. Aucun paiement demandé pour les essais.</p>'+planCards()+formfield('Nom de l’entreprise','companyName')+button('Créer mon espace','createCompany','gold full',state.authBusy?'disabled':'')+'<details><summary>J’ai reçu une invitation</summary>'+formfield('Code d’invitation','inviteToken',sessionStorage.getItem('punch-invite')||'')+button('Rejoindre mon équipe','acceptInvitation','full')+'</details>'+button('Se déconnecter','logout','full'))+'<div id="authError" class="notice danger" role="alert" '+(!state.authError?'hidden':'')+'>'+e(state.authError)+'</div><div id="authNotice" class="notice" role="status" '+(!state.authNotice?'hidden':'')+'>'+e(state.authNotice)+'</div><div class="small muted center">Tes données sont sauvegardées dans ton espace PUNCH.</div></div>'}
function authMessage(message,isError=false){state.authError=isError?message:'';state.authNotice=isError?'':message;for(const [id,text] of [['authError',state.authError],['authNotice',state.authNotice]]){const n=$(id);if(n){n.textContent=text;n.hidden=!text}}}
function authFailure(err){const code=err?.code||'';const text=err?.message||'';const messages={invalid_credentials:'Courriel ou mot de passe incorrect. Si tu viens de t’inscrire, confirme ton courriel.',email_not_confirmed:'Confirme ton courriel avant de te connecter. Tu peux renvoyer le lien ci-dessus.',user_already_exists:'Ce compte existe déjà. Connecte-toi ou utilise « Mot de passe oublié ».',over_email_send_rate_limit:'Trop de courriels demandés. Patiente quelques minutes avant de réessayer.',email_address_not_authorized:'L’envoi de courriels est limité par la configuration du serveur. Le service de courriel doit être configuré.',signup_disabled:'Les inscriptions sont désactivées sur le serveur.',weak_password:'Choisis un mot de passe plus robuste (au moins 8 caractères).'};authMessage(messages[code]||(/fetch|network|abort/i.test(text)?'Connexion impossible. Vérifie ton réseau et réessaie.':text||'Impossible de terminer cette action.'),true)}

function base(){if(isEssential())return essentialBase();const t=new Date();const name=state.account?.companies?.name||'PUNCH';const n=[['home','⌂','Accueil'],['hours','◷','Mes heures'],['orders','🛒','Commande'],['messages','▤','Message'],['more','▦','Plus']];return '<div class="wrap"><div class="pitch"><div class="kicker">PUNCH 360° · TEST WEB</div><h1>Le chantier <b>dans ta poche.</b></h1><p>Une vraie session, de vrais chantiers et des heures de test enregistrées sur le serveur.</p><p class="small muted">Accès mobile Android / iPhone / PC</p></div><div class="phone"><div class="backdrop"></div><div class="statusline"><span id="topclock">'+t.toLocaleTimeString('fr-CA',{hour:'2-digit',minute:'2-digit'})+'</span><span>◉ ▴ ▰</span></div><header class="header"><span style="font-size:29px">👷</span><div class="logo">PUNCH <span>360°</span><span class="date">'+t.toLocaleDateString('fr-CA',{weekday:'long',day:'numeric',month:'short',year:'numeric'})+'</span></div><button class="iconbutton" data-action="subpage" data-id="notifications" aria-label="Notifications">♧ '+state.notifications.filter(n=>!n.read_at).length+'</button><button class="iconbutton" data-action="refresh" aria-label="Actualiser">⟳</button><button class="iconbutton" data-action="profile" aria-label="Mon profil">👤</button></header><main id="main">'+(state.recovery?authHTML():member()?page():authHTML())+'</main><div class="banner">'+(member()?(state.localPending?'● HORS LIGNE · '+state.localPending+' PUNCH(S) CONSERVÉ(S) SUR CET APPAREIL':'● ALPHA CONNECTÉE — NE PAS UTILISER POUR LA PAIE'):'● ALPHA — COMPTE DE TEST')+'</div>'+(member()?'<nav class="nav">'+n.map(a=>'<button class="'+(state.section===a[0]||(state.section==='jobs'&&a[0]==='home')||(state.section==='detail'&&a[0]==='home')||(state.section==='sub'&&a[0]==='more')?'active':'')+'" data-action="navigate" data-id="'+a[0]+'"><i>'+a[1]+'</i><span>'+a[2]+'</span></button>').join('')+'</nav>':'')+'<div class="toast" id="toast" style="display:none"></div></div></div>'}
function draw(){document.documentElement.classList.toggle('essential',isEssential());const focus=document.activeElement,focusId=focus?.id,cursor=focus?.selectionStart??null;const draft={};if(!member()||state.recovery)for(const id of ['email','password','companyName','inviteToken','newPassword','confirmPassword']){if($(id))draft[id]=$(id).value}const oldTop=$('main')?.scrollTop||0;$('root').innerHTML=base();for(const [id,value] of Object.entries(draft)){if($(id))$(id).value=value}const main=$('main');if(main)main.scrollTop=oldTop; if(focusId&&$(focusId)&&['INPUT','TEXTAREA'].includes(focus?.tagName||'')){try{$(focusId).focus();if(cursor!=null)$(focusId).setSelectionRange(cursor,cursor)}catch{}}}
function page(){if(isEssential())return essentialPage();switch(state.section){case 'home':return home();case 'jobs':return jobsPage();case 'detail':return detailPage();case 'hours':return hoursPage();case 'orders':return ordersPage();case 'messages':return messagesPage();case 'more':return morePage();case 'sub':return subPage();default:return home()}}
function currentSession(){return state.sessions.find(s=>!s.ended_at)||null}
function activeSegment(){return state.segments.find(s=>!s.ended_at)||null}
function totals(from){const gross=state.segments.reduce((sum,s)=>sum+Math.max(0,Math.min(s.ended_at?Date.parse(s.ended_at):state.time,state.time)-Math.max(Date.parse(s.started_at),from)),0);const pauses=state.breaks.reduce((sum,b)=>sum+Math.max(0,Math.min(b.ended_at?Date.parse(b.ended_at):state.time,state.time)-Math.max(Date.parse(b.started_at),from)),0);return Math.max(0,gross-pauses)}
function clockTotals(){const d=new Date(state.time),mon=(d.getDay()+6)%7;const week=new Date(d.getFullYear(),d.getMonth(),d.getDate()-mon).getTime(),yr=new Date(d.getFullYear(),0,1).getTime();return{week:totals(week),year:totals(yr)}}
function nextJob(){const planned=state.shifts.filter(s=>s.user_id===state.user.id&&Date.parse(s.starts_at)>Date.now()&&s.job_id!==state.selected).map(s=>getJob(s.job_id)).find(Boolean);if(planned)return planned;const today=new Date().toISOString().slice(0,10);return state.assignments.filter(a=>a.planned_start>today&&a.job_id!==state.selected).sort((a,b)=>a.planned_start.localeCompare(b.planned_start)).map(a=>getJob(a.job_id)).find(Boolean)}
function jobTile(j,label,upcoming=false){return '<div class="card jobtile" data-action="openJobs"><div class="between" style="margin-bottom:7px"><b style="font-size:13px">'+label+'</b><span class="pill '+(upcoming||!currentSession()?'':'green')+'">'+(upcoming?'À venir':currentSession()?'En cours':'Sélectionnée')+'</span></div><div class="body"><img src="'+e(j.photo_url||img)+'" alt="Photo chantier"/><div class="grow"><div class="jobname">#'+e(j.number)+' — '+e(j.name)+'</div><div class="jobaddr">'+e(j.address)+'</div><div class="small muted">'+(upcoming?'Prochaine affectation':'Plans, commandes, punchs')+'</div></div><button class="iconbutton" style="width:32px;height:32px" data-action="maps" data-id="'+j.id+'" aria-label="Itinéraire">➤</button></div></div>'}
function home(){const j=selectedJob(),t=clockTotals(),active=currentSession(),start=active?Date.parse(active.started_at):null,next=nextJob();return '<div class="home"><div class="weather">'+card('<span class="weathericon">🌤</span><div><b>Météo</b><div class="small muted">À connecter</div></div>')+card('<span class="weathericon">📍</span><div class="grow"><b>GPS chantier</b><div class="small muted">'+(state.position?'Position détectée':'Sur demande')+'</div></div><button class="iconbutton" data-action="gps" aria-label="Activer GPS">⌖</button>')+'</div><div class="punchblock"><button class="punch '+(active?'out':'')+'" data-action="punch" '+(!j||state.busy?'disabled':'')+'><span class="symbol">'+(active?'■':'▶')+'</span><strong>PUNCH '+(active?'OUT':'IN')+'</strong><span class="small">#'+e(j?.number||'—')+' '+e(j?.name||'Aucune job')+'</span><span class="clock" id="liveTimer">'+elapsed(active?state.time-start:0)+'</span></button><button class="jobchoose" data-action="switchJobs">⌖ Changer de job ›</button></div><div class="stats">'+card('<div class="small muted">◷ Cette semaine</div><strong id="weekTotal">'+mins(t.week)+'</strong>')+card('<div class="small muted">▥ Cette année</div><strong id="yearTotal">'+mins(t.year)+'</strong>')+'</div>'+(j?jobTile(j,'▣ Job en cours'):card('<p>Commence par créer ou choisir une job.</p>'+button('Toutes les jobs','openJobs','gold')))+(next?jobTile(next,'▦ Prochain chantier',true):'')+card('<div class="between"><div><b>📄 Documents de chantier</b><div class="small muted">'+(state.documents.filter(d=>d.job_id===state.selected).length||0)+' fichier(s) sur cette job</div></div>'+button('Ouvrir','openDetail')+'</div>')+'</div>'}
function jobList(){let items=state.jobs.filter(j=>(state.filter!=='mine'||state.assignments.some(a=>a.job_id===j.id))&&(!state.search||[j.name,j.number,j.address].join(' ').toLowerCase().includes(state.search.toLowerCase())));if(state.filter==='near'&&state.position)items=items.filter(j=>j.latitude!=null&&j.longitude!=null).map(j=>({...j,distance:distance(state.position,{latitude:j.latitude,longitude:j.longitude})})).sort((a,b)=>a.distance-b.distance);return items}
function distance(a,b){const r=n=>n*Math.PI/180,dx=r(b.latitude-a.latitude),dy=r(b.longitude-a.longitude);const h=Math.sin(dx/2)**2+Math.cos(r(a.latitude))*Math.cos(r(b.latitude))*Math.sin(dy/2)**2;return 6371*2*Math.asin(Math.sqrt(h))}
function jobsPage(){const list=jobList();return heading('Toutes les jobs','home')+'<div class="group"><input id="jobSearch" class="field" placeholder="Rechercher un chantier ou numéro…" value="'+e(state.search)+'"></div><div class="tabs">'+[['all','Toutes'],['mine','Mes jobs'],['near','À proximité']].map(v=>'<button data-action="filter" data-id="'+v[0]+'" class="'+(state.filter===v[0]?'active':'')+'">'+v[1]+'</button>').join('')+'</div>'+card('<div class="between"><b>📍 Carte des chantiers</b>'+button('Actualiser GPS','gps')+'</div><div id="geoMap" class="map" style="margin-top:8px"></div><div class="small muted" style="margin-top:7px">'+(state.position?'GPS : '+state.position.latitude.toFixed(4)+', '+state.position.longitude.toFixed(4):'Autorise le GPS pour voir les chantiers proches.')+'</div>')+'<div class="between"><b>'+list.length+' chantier(s)</b><span class="small muted">'+(state.routeMode==='switch'?'Choisir pour transférer':'Ouvrir la fiche')+'</span></div>'+list.map(j=>'<button class="listitem" data-action="detail" data-id="'+j.id+'"><img src="'+e(j.photo_url||img)+'" alt="Chantier"/><span class="grow"><b>#'+e(j.number)+' — '+e(j.name)+'</b><small>'+e(j.address)+'</small><small>'+(j.id===state.selected?'Actuelle':state.assignments.some(a=>a.job_id===j.id)?'Ma job':'Disponible')+(j.distance!=null?' · '+j.distance.toFixed(1)+' km':'')+'</small></span><span class="arrow">›</span></button>').join('')+(list.length?'':'<div class="small muted center">Aucun chantier correspondant.</div>')}
function detailPage(){const j=getJob(state.detailId);if(!j)return card('Chantier introuvable.');const ps=state.segments.filter(s=>s.job_id===j.id&&state.archived.includes(s.id)===!!state.showArchives),docs=state.documents.filter(d=>d.job_id===j.id),orders=state.orders.filter(o=>o.job_id===j.id);return heading('#'+e(j.number)+' — '+e(j.name),'jobs')+card('<div class="row"><img class="thumb" src="'+e(j.photo_url||img)+'" alt="Chantier"><div class="grow"><b>'+e(j.name)+'</b><div class="small muted">'+e(j.address)+'</div></div></div><div class="buttonrow" style="margin-top:10px">'+button('➤ Waze','waze')+button('⌖ Google Maps','googleMaps')+'</div>')+card('<div class="between"><b>Job sélectionnée</b><span class="pill '+(j.id===state.selected?'green':'')+'">'+(j.id===state.selected?'Actuelle':'Disponible')+'</span></div>'+button(currentSession()?'⇄ Transférer les heures ici':'✓ Sélectionner pour Punch IN','selectDetail','green full')+'</div>')+card('<b>📄 Plans et documents</b>'+(docs.length?docs.map(d=>'<div class="hoursitem"><div class="grow"><b>'+e(d.name)+'</b><small>'+e(d.kind)+' · Version '+d.version+(d.requires_ack?' · Lecture obligatoire':'')+'</small></div></div>').join(''):'<p class="small muted">Aucun document téléversé.</p>')+'<div class="small muted">Ouverture PDF et confirmations de lecture : à terminer.</div>')+card('<div class="between"><b>🛒 Commandes</b><span class="pill">'+orders.length+'</span></div>'+orders.slice(0,3).map(o=>'<div class="hoursitem"><span class="grow small">'+e(o.note||'Commande')+'</span><span class="pill">'+stateText(o.status)+'</span></div>').join('')+button('Faire une commande','orderPage','full') )+card('<div class="between"><b>◷ Mes punchs sur cette job</b>'+button(state.showArchives?'Actifs':'Archives','archiveToggle')+'</div>'+(ps.length?ps.map(s=>'<div class="hoursitem"><div class="grow"><b>'+when(s.started_at)+' → '+(s.ended_at?when(s.ended_at):'En cours')+'</b><small>'+mins((s.ended_at?Date.parse(s.ended_at):state.time)-Date.parse(s.started_at))+'</small></div>'+button(state.showArchives?'Restaurer':'⋮ Archiver','archive:'+s.id)+'</div>').join(''):'<p class="muted small">Aucun punch à afficher.</p>'))}
function hoursPage(){const t=clockTotals();return heading('Mes heures')+button('Exporter mes heures CSV','exportHours','full')+'<div class="stats">'+card('<div class="small muted">Cette semaine</div><strong>'+mins(t.week)+'</strong>')+card('<div class="small muted">Cette année</div><strong>'+mins(t.year)+'</strong>')+'</div>'+card('<div class="between"><b>Historique de mes journées</b><span class="pill">'+state.sessions.length+' session(s)</span></div>'+(state.sessions.length?state.sessions.slice(0,80).map(s=>'<button class="listitem" data-action="hoursDetail" data-id="'+s.id+'"><span>◷</span><span class="grow"><b>'+new Date(s.started_at).toLocaleDateString('fr-CA')+'</b><small>'+when(s.started_at)+' → '+(s.ended_at?when(s.ended_at):'En cours')+'</small></span><b>'+mins((s.ended_at?Date.parse(s.ended_at):state.time)-Date.parse(s.started_at))+'</b></button>').join(''):'<p class="small muted">Aucune heure encore enregistrée.</p>'))+card('<b>Corrections d’heures</b><div class="small muted">L’employé demande; la correction attend une approbation. Aucune heure officielle ne change automatiquement.</div><div class="group"><select id="sessionCorrect" class="field"><option value="">Choisir une journée</option>'+state.sessions.map(s=>'<option value="'+s.id+'">'+new Date(s.started_at).toLocaleDateString('fr-CA')+'</option>').join('')+'</select></div>'+formfield('Nouvelle entrée (heure locale)','correctionStart','','datetime-local')+formfield('Nouvelle sortie (heure locale)','correctionEnd','','datetime-local')+'<div class="group"><textarea id="correctionReason" class="field" placeholder="Raison de la correction…"></textarea></div>'+button('Soumettre la correction','correction','gold full')+'</div>')+card('<b>Demandes de correction</b>'+(state.corrections.length?state.corrections.map(r=>'<div class="hoursitem"><div class="grow small">'+e(r.reason)+'<small>'+when(r.created_at)+'</small></div><span class="pill">'+stateText(r.status)+'</span></div>').join(''):'<p class="small muted">Aucune demande.</p>'))}
function ordersPage(){const j=selectedJob();return heading('Commandes de matériel')+card('<b>Commande pour : '+e(j?'#'+j.number+' — '+j.name:'Aucune job')+'</b><div class="small muted">Description libre, quantités et matériel à commander. Catalogue photo et suivi complet : à développer.</div><div class="group"><textarea id="materialNote" class="field" placeholder="Exemple : 3 boîtes de vis 3 pouces, 10 feuilles de contreplaqué…"></textarea></div>'+button('Envoyer la commande','submitOrder','gold full',j?'':'disabled')+'</div>')+card('<div class="between"><b>Mes commandes</b><span class="pill">'+state.orders.length+'</span></div>'+(state.orders.length?state.orders.map(o=>'<div class="hoursitem"><div class="grow"><b>Job #'+e(getJob(o.job_id)?.number||'—')+'</b><small>'+when(o.created_at)+' · '+e(o.note||'Matériel')+'</small></div><span class="pill">'+stateText(o.status)+'</span></div>').join(''):'<p class="small muted">Aucune commande envoyée.</p>'))}
