function morePage(){return heading('Plus')+card('<div class="row"><span style="font-size:26px">👤</span><div><b>'+e(state.profile?.full_name||state.user.email||'Employé')+'</b><div class="small muted">'+e(labelRole(state.account.role))+' · '+e(state.account.companies?.name)+'</div><div class="small muted">Abonnement : '+stateText(state.account.companies?.billing_status)+'</div></div></div>')+[['profile','👤','Mon profil'],['contacts','📞',"Contacts d'urgence"],['credentials','🪪','Carte CCQ et compétences'],['leave','📅','Vacances, congés et absences'],['schedule','🗓','Mon horaire'],...(!manager()?[['documents','📄','Documents de chantier']]:[]),...(manager()?[['admin','🏗','Gestion des jobs'],['teams','👷','Gestion des équipes'],['approvals','✅','Demandes à approuver'],['geofence','📍','Rayon de punch et validation GPS'],['invitations','✉','Inviter des membres'],['documents','📄','Documents de chantier']]:state.account?.role==='lead'?[['teams','👷','Mon équipe']]:[]),['settings','⚙','Paramètres']].map(x=>'<button class="listitem" data-action="subpage" data-id="'+x[0]+'"><span class="icon">'+x[1]+'</span><span class="grow"><b>'+x[2]+'</b></span><span class="arrow">›</span></button>').join('')+card(button('Se déconnecter','logout','full'))}
