async function reviewRecord(rpc,id,approve){const note=prompt('Motif de la décision (minimum 3 caractères)');if(!note||note.trim().length<3)return;try{const r=await sb.rpc(rpc,{p_request:id,p_approve:approve,p_note:note});if(r.error)throw r.error;await reload({quiet:true});toast('Décision enregistrée et historisée')}catch(err){error(err)}}
async function advanceOrder(id,status){const note=prompt('Commentaire de suivi (minimum 3 caractères)');if(!note||note.trim().length<3)return;try{const r=await sb.rpc('advance_material_order',{p_order:id,p_status:status,p_note:note});if(r.error)throw r.error;await reload({quiet:true});toast('Commande mise à jour')}catch(err){error(err)}}
async function setWeek(close){const week=$val('payrollWeek');if(!week)return toast('Choisis le lundi de la semaine.');const reason=prompt('Motif de '+(close?'fermeture':'réouverture'));if(!reason||reason.trim().length<3)return;try{const r=await sb.rpc('set_payroll_week',{p_company:company(),p_week:week,p_close:close,p_reason:reason});if(r.error)throw r.error;await reload({quiet:true});toast(close?'Semaine fermée':'Semaine rouverte')}catch(err){error(err)}}
function csvCell(v){let t=String(v??'');if(/^[=+@\t\r-]/.test(t))t="'"+t;return '"'+t.replace(/"/g,'""')+'"'}
async function exportHours(){try{
 let rows=[],offset=0;while(true){let q=sb.from('punch_segments').select('id,session_id,job_id,started_at,ended_at,punch_sessions!inner(user_id)').eq('company_id',company()).order('id').range(offset,offset+499);if(!manager()||state.section==='hours')q=q.eq('punch_sessions.user_id',state.user.id);const r=await q;if(r.error)throw r.error;rows.push(...(r.data||[]));if(r.data.length<500)break;offset+=500;}
 let breaks=[],breakOffset=0;while(true){const b=await sb.from('punch_breaks').select('session_id,started_at,ended_at').eq('company_id',company()).order('id').range(breakOffset,breakOffset+499);if(b.error)throw b.error;breaks.push(...b.data);if(b.data.length<500)break;breakOffset+=500;}
 const paused=r=>breaks.filter(b=>b.session_id===r.session_id).reduce((sum,b)=>sum+Math.max(0,Math.min(Date.parse(b.ended_at||r.ended_at),Date.parse(r.ended_at))-Math.max(Date.parse(b.started_at),Date.parse(r.started_at))),0);
 const data=[['Segment','Employé',isEssential()?'Lieu':'Job','Entrée ISO','Sortie ISO','Heures brutes','Pauses non payées (h)','Heures nettes','Anomalie'],...rows.map(r=>[r.id,r.punch_sessions.user_id,isEssential()?'Établissement':getJob(r.job_id)?.number||r.job_id,r.started_at,r.ended_at||'',r.ended_at?((Date.parse(r.ended_at)-Date.parse(r.started_at))/3600000).toFixed(4):'',r.ended_at?(paused(r)/3600000).toFixed(4):'',r.ended_at?((Date.parse(r.ended_at)-Date.parse(r.started_at)-paused(r))/3600000).toFixed(4):'',!r.ended_at?'SORTIE MANQUANTE':Date.parse(r.ended_at)-Date.parse(r.started_at)>16*3600000?'PLUS DE 16H':''])];
 const blob=new Blob(['\uFEFF'+data.map(r=>r.map(csvCell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'});const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='PUNCH-heures-'+new Date().toISOString().slice(0,10)+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);
}catch(err){error(err)}}


function schedulePage(){if(isEssential())return essentialSchedule();return heading('Horaire et affectations','more')+(manager()?card('<b>Planifier un quart</b><div class="group"><label>Employé</label><select id="shiftUser" class="field">'+state.members.map(m=>'<option value="'+e(m.user_id)+'">'+e(m.user_id.slice(0,8))+' · '+e(labelRole(m.role))+'</option>').join('')+'</select></div>'+jobSelect('shiftJob')+formfield('Début (heure de cet appareil)','shiftStart','','datetime-local')+formfield('Fin (heure de cet appareil)','shiftEnd','','datetime-local')+formfield('Note','shiftNote')+button('Affecter au chantier','scheduleShift','gold full')):'')+card('<b>Quarts planifiés</b>'+state.shifts.map(x=>'<div class="group"><b>#'+e(getJob(x.job_id)?.number||'—')+' · '+e(x.user_id.slice(0,8))+'</b><p>'+when(x.starts_at)+' → '+when(x.ends_at)+'</p><p>'+e(x.note)+'</p>'+(manager()?button('Annuler le quart','cancelShift','',`data-id="${e(x.id)}"`):'')+'</div>').join(''));}
function jobSelect(id){if(isEssential())return '<input type="hidden" id="'+id+'" value="'+e(state.account.companies.default_punch_job_id||state.selected)+'" />';return '<div class="group"><label>Chantier</label><select id="'+id+'" class="field">'+state.jobs.map(j=>'<option value="'+e(j.id)+'">#'+e(j.number)+' — '+e(j.name)+'</option>').join('')+'</select></div>'}
async function scheduleShift(){try{const start=$val('shiftStart'),end=$val('shiftEnd');if(!start||!end)return toast('Début et fin requis.');const r=await sb.rpc('schedule_shift',{p_company:company(),p_user:$val('shiftUser'),p_job:$val('shiftJob'),p_start:new Date(start).toISOString(),p_end:new Date(end).toISOString(),p_note:$val('shiftNote')});if(r.error)throw r.error;await reload({quiet:true});toast('Quart planifié')}catch(err){error(err)}}
async function cancelShift(id){const reason=prompt('Motif d’annulation');if(!reason)return;try{const r=await sb.rpc('cancel_shift',{p_shift:id,p_reason:reason});if(r.error)throw r.error;await reload({quiet:true})}catch(err){error(err)}}
function invitationPage(){return heading('Invitations sécurisées','more')+(manager()?card('<p>Un abonnement actif et une place disponible sont obligatoires. Le destinataire doit confirmer son courriel.</p>'+formfield('Courriel du membre','inviteEmail','','email')+'<div class="group"><label>Rôle attribué</label><select id="inviteRole" class="field"><option value="employee">Employé</option><option value="lead">Chef d’équipe</option><option value="admin">Admin</option></select></div>'+button('Créer le lien d’invitation','createInvitation','gold full')+'<div id="inviteResult"></div>'):'')+card(formfield('Code d’invitation','inviteToken')+button('Rejoindre la compagnie invitante','acceptInvitation','full'));}
async function createInvitation(){try{const r=await sb.rpc('create_company_invitation',{p_company:company(),p_email:$val('inviteEmail'),p_role:$val('inviteRole'),p_hours:72});if(r.error)throw r.error;const url=OAUTH_REDIRECT+'?invite='+encodeURIComponent(r.data.token);$('inviteResult').innerHTML='<p>Valide 72 heures. Partage ce lien avec le destinataire :</p><textarea class="field" readonly>'+e(url)+'</textarea><p class="small">Le lien contient un code à usage unique. Copie-le maintenant.</p>'}catch(err){error(err)}}
async function acceptInvitation(){try{const token=$val('inviteToken');if(!token)return toast('Code d’invitation requis');const r=await sb.rpc('accept_company_invitation',{p_token:token});if(r.error)throw r.error;sessionStorage.removeItem('punch-invite');await initialize();toast('Compagnie rejointe avec le rôle attribué')}catch(err){error(err)}}
function documentPage(){return heading('Plans et documents','more')+(manager()?card('<b>Ajouter une révision PDF privée</b>'+jobSelect('documentJob')+formfield('Titre','documentTitle')+formfield('Version','documentVersion','1','number','min="1"')+'<div class="group"><label>Fichier PDF (25 Mo maximum)</label><input class="field" id="documentFile" type="file" accept="application/pdf" /></div><label><input id="documentAck" type="checkbox" checked /> Confirmation de lecture requise</label>'+button('Publier le PDF','uploadDocument','gold full')):'')+state.documents.map(d=>card('<b>'+e(d.name)+' · v'+d.version+'</b><p class="small">#'+e(getJob(d.job_id)?.number||'—')+'</p>'+button('Ouvrir le PDF privé','openDocument','',`data-id="${e(d.id)}"`)+(d.requires_ack?(state.acks.some(a=>a.document_id===d.id)?'<p>✓ Lecture confirmée</p>':button('Confirmer avoir lu cette version','ackDocument','gold',`data-id="${e(d.id)}"`)):'') )).join('');}
async function uploadDocument(){try{const file=$('documentFile')?.files?.[0],job=$val('documentJob'),title=$val('documentTitle'),version=Number($val('documentVersion'));if(!file||file.size>26214400||!title||!Number.isInteger(version)||version<1)return toast('PDF, titre et version valides requis.');const header=await file.slice(0,5).text();if(header!=='%PDF-')return toast('Ce fichier n’est pas un PDF.');const path=company()+'/'+job+'/'+crypto.randomUUID()+'.pdf';const upload=await sb.storage.from('job-documents').upload(path,file,{contentType:'application/pdf',upsert:false});if(upload.error)throw upload.error;const r=await sb.from('job_documents').insert({company_id:company(),job_id:job,name:title,kind:'plan',storage_path:path,version,requires_ack:$('documentAck').checked,created_by:state.user.id});if(r.error)throw r.error;await reload({quiet:true});toast('Version PDF publiée dans le stockage privé')}catch(err){error(err)}}
async function openDocument(id){const d=state.documents.find(d=>d.id===id);if(!d)return;const popup=window.open('about:blank','_blank');try{const r=await sb.storage.from('job-documents').createSignedUrl(d.storage_path,60);if(r.error)throw r.error;if(popup){popup.opener=null;popup.location=r.data.signedUrl}else toast('Autorise les fenêtres pour ouvrir le PDF')}catch(err){popup?.close();error(err)}}
async function ackDocument(id){if(!confirm('Confirmer avoir pris connaissance de cette version ?'))return;try{const r=await sb.from('document_acknowledgements').insert({document_id:id,user_id:state.user.id});if(r.error&&r.error.code!=='23505')throw r.error;await reload({quiet:true})}catch(err){error(err)}}
const receivedInvitation=new URLSearchParams(location.search).get('invite');if(receivedInvitation){sessionStorage.setItem('punch-invite',receivedInvitation);history.replaceState(null,'',location.pathname);}


async function freshPunchFix(){return new Promise(resolve=>{if(!navigator.geolocation)return resolve(null);navigator.geolocation.getCurrentPosition(p=>resolve({latitude:p.coords.latitude,longitude:p.coords.longitude,accuracy:p.coords.accuracy}),()=>resolve(null),{enableHighAccuracy:true,timeout:12000,maximumAge:0})})}
const journalInstances=new Map();
function punchJournal(){const key=state.user.id+':'+company();if(!journalInstances.has(key))journalInstances.set(key,new PunchJournal({company:company(),user:state.user.id,withLock:fn=>navigator.locks?navigator.locks.request('punch-journal:'+key,fn):fn(),uuid:()=>crypto.randomUUID(),storage:{get:async key=>localStorage.getItem(key),set:async(key,value)=>localStorage.setItem(key,value)},send:async event=>{if(!navigator.onLine)throw Error('Réseau indisponible');const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),10000);try{const request=event.action.startsWith('break_')?sb.rpc('sync_break_event',{p_event:event.id,p_company:event.company,p_action:event.action,p_occurred_at:event.occurredAt,p_offline:event.offline,p_previous:event.previous}):sb.rpc('sync_punch_event',{p_event:event.id,p_company:event.company,p_action:event.action,p_occurred_at:event.occurredAt,p_offline:event.offline,p_job:event.job,p_latitude:event.fix?.latitude??null,p_longitude:event.fix?.longitude??null,p_accuracy:event.fix?.accuracy??null,p_previous:event.previous});const r=await request.abortSignal(controller.signal);if(r.error)throw r.error;return r.data;}finally{clearTimeout(timer)}}}));return journalInstances.get(key);}
function saveOfflineSnapshot(){if(!member())return;localStorage.setItem('punch-snapshot:'+state.user.id,JSON.stringify({company:company(),jobs:state.jobs,assignments:state.assignments,shifts:state.shifts,serverPunch:state.serverPunch,selected:state.selected}));}
function restoreOfflineSnapshot(){if(!state.user)return;const data=JSON.parse(localStorage.getItem('punch-snapshot:'+state.user.id)||'null');if(data){state.jobs=data.jobs||[];state.assignments=data.assignments||[];state.shifts=data.shifts||[];state.serverPunch=data.serverPunch||{sessions:[],segments:[]};state.sessions=state.serverPunch.sessions;state.segments=state.serverPunch.segments;state.breaks=state.serverPunch.breaks||[];state.selected=data.selected;}}
async function locatedPunch(action,job){const at=new Date().toISOString(),fix=action.startsWith('break_')?null:await freshPunchFix(),journal=punchJournal();const event=await journal.append(action,job,fix,at);const sync=await journal.flush(),saved=sync.events.find(e=>e.id===event.id);if(saved?.status==='conflict')toast('Événement conservé et conflit transmis à l’administration');return {...saved?.result,review_status:saved?.status==='pending'?'local':saved?.result?.review_status};}
window.addEventListener('online',()=>{if(member())reload({quiet:true})});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&member())reload({quiet:true})});
setInterval(()=>{if(member()&&!state.busy)reload({quiet:true})},30000);

const locationLabel={inside:'Dans le rayon',outside:'Hors rayon',missing:'GPS absent',inaccurate:'GPS imprécis',job_unconfigured:'Coordonnées chantier manquantes'};
function geofenceReviewCard(){return breakApprovals()+card('<b>Conflits de synchronisation conservés</b>'+state.receipts.filter(r=>r.result?.sync_status==='conflict').map(r=>'<div class="group">'+e(r.user_id.slice(0,8))+' · '+e(r.action)+' · '+when(r.occurred_at)+'<p>'+e(r.result.message)+'</p></div>').join(''))+card('<b>Punchs GPS en attente</b>'+state.locationChecks.filter(c=>c.review_status==='pending').map(c=>'<div class="group"><b>#'+e(getJob(c.job_id)?.number||'—')+' · '+e(locationLabel[c.location_status])+(c.offline?' · HORS LIGNE':'')+'</b><p class="small">'+e(c.user_id.slice(0,8))+' · '+when(c.recorded_at)+' · '+e(c.action)+'</p><p class="small">Distance : '+(c.distance_m==null?'inconnue':Math.round(c.distance_m)+' m')+' / maximum '+c.radius_m+' m · précision '+(c.accuracy_m==null?'inconnue':Math.round(c.accuracy_m)+' m')+'</p>'+button('Accepter le punch','reviewLocation','gold',`data-id="${e(c.id)}"`)+button('Corriger les heures','correctLocation','',`data-id="${e(c.id)}"`)+'</div>').join(''));}
function geofencePage(){if(!manager())return heading('Accès réservé','more');return heading(isEssential()?'Périmètre de l’établissement':'Rayon de punch par job','more')+card('<p>Le rayon est mesuré depuis les coordonnées de l’établissement. Un punch hors rayon est conservé et attend une validation. Le GPS absent ou imprécis nécessite aussi une validation.</p>')+state.jobs.map(j=>card('<b>'+e(isEssential()?'Mon établissement':'#'+j.number+' — '+j.name)+'</b>'+formfield('Latitude','geoLat-'+j.id,j.latitude??'','number','step="any"')+formfield('Longitude','geoLon-'+j.id,j.longitude??'','number','step="any"')+formfield('Rayon maximal (10 à 10 000 mètres)','geoRadius-'+j.id,j.punch_radius_m||200,'number','min="10" max="10000"')+button('Enregistrer le périmètre','saveGeofence','gold',`data-id="${e(j.id)}"`))).join('')+geofenceReviewCard();}
async function saveGeofence(id){try{const lat=$val('geoLat-'+id),lon=$val('geoLon-'+id),radius=Number($val('geoRadius-'+id));if(!lat||!lon||!Number.isFinite(Number(lat))||!Number.isFinite(Number(lon))||!Number.isInteger(radius))return toast('Coordonnées et rayon valides requis');const r=await sb.from('jobs').update({latitude:Number(lat),longitude:Number(lon),punch_radius_m:radius}).eq('id',id).eq('company_id',company()).select('id').single();if(r.error)throw r.error;await reload({quiet:true});toast('Rayon du chantier enregistré')}catch(err){error(err)}}
async function reviewLocation(id,correct){const note=prompt('Motif de validation ou de correction (minimum 3 caractères)');if(!note||note.trim().length<3)return;let start=null,end=null;if(correct){const a=prompt('Nouvelle entrée ISO avec fuseau (vide = inchangée)');if(a===null)return;const b=prompt('Nouvelle sortie ISO avec fuseau (vide = inchangée)');if(b===null)return;try{start=a?new Date(a).toISOString():null;end=b?new Date(b).toISOString():null}catch{return toast('Dates invalides')}if(!start&&!end)return toast('Indique au moins une heure à corriger.');}try{const r=await sb.rpc('review_punch_location',{p_check:id,p_note:note,p_start:start,p_end:end});if(r.error)throw r.error;await reload({quiet:true});toast(correct?'Heures corrigées et validation historisée':'Punch accepté et historisé')}catch(err){error(err)}}
function notificationsPage(){return heading('Notifications','more')+state.notifications.map(n=>card('<b>'+e(n.title)+'</b><p>'+e(n.body)+'</p><p class="small">'+when(n.created_at)+'</p>'+(!n.read_at?button('Marquer comme lue','readNotification','',`data-id="${e(n.id)}"`):'<p class="small">Lue</p>')+(n.location_check_id&&manager()?button('Voir les punchs à valider','subpage','gold','data-id="geofence"'):'') )).join('');}
async function readNotification(id){try{const r=await sb.from('app_notifications').update({read_at:new Date().toISOString()}).eq('id',id).eq('recipient_id',state.user.id);if(r.error)throw r.error;await reload({quiet:true})}catch(err){error(err)}}


function isEssential(){return state.account?.companies?.product_edition==='essential'||(!member()&&state.creationEdition==='essential')}
function siteLabel(id){return isEssential()?'Établissement':'#'+(getJob(id)?.number||'—')}
function planCards(){return '<div class="plan-cards"><button type="button" class="plan-card '+(state.creationEdition==='essential'?'chosen':'')+'" data-action="chooseEdition" data-id="essential"><span class="plan-kicker">BUREAUX · MANUFACTURES</span><strong>PUNCH Essentiel</strong><span>Punch, pauses, heures et congés. Simplement.</span><b>19 $ CA / mois*</b><small>5 personnes incluses · +3 $ / personne</small></button><button type="button" class="plan-card '+(state.creationEdition==='construction'?'chosen':'')+'" data-action="chooseEdition" data-id="construction"><span class="plan-kicker">CHANTIERS · ÉQUIPES MOBILES</span><strong>PUNCH Construction</strong><span>Jobs, matériel, plans et équipes.</span><b>49 $ CA / mois*</b><small>5 personnes incluses · +7 $ / personne</small></button></div><p class="small muted">* Proposition de tarification, hors taxes. Paiement non activé.</p>'}
function essentialToday(){const d=new Date(state.time);return totals(new Date(d.getFullYear(),d.getMonth(),d.getDate()).getTime())}
function essentialBase(){const tabs=[['home','◉','Punch'],['hours','◷','Heures'],['schedule','▦','Horaire'],['more','☷','Plus']];return '<div class="wrap"><aside class="pitch essential-pitch"><div class="kicker">PUNCH ESSENTIEL</div><h1>Du temps.<br>De la <b>simplicité.</b></h1><p>Le pointage qui laisse respirer votre journée.</p><div class="zen-orbit">◌</div><p class="small">Bureaux · ateliers · manufactures</p></aside><div class="phone"><header class="header"><div class="essential-brand"><span class="brand-mark">p</span><div>PUNCH <span>Essentiel</span></div></div><button class="iconbutton" data-action="subpage" data-id="notifications" aria-label="Notifications">♧ '+state.notifications.filter(n=>!n.read_at).length+'</button></header><main id="main">'+(state.recovery?authHTML():member()?essentialPage():authHTML())+'</main><div class="banner">'+(member()?(state.localPending?'◌ '+state.localPending+' événement(s) conservé(s) sur cet appareil':'Données de test · validation terrain à effectuer'):'PUNCH · choisir la simplicité')+'</div>'+(member()?'<nav class="nav">'+tabs.map(t=>'<button class="'+(state.section===t[0]?'active':'')+'" data-action="navigate" data-id="'+t[0]+'"><i>'+t[1]+'</i><span>'+t[2]+'</span></button>').join('')+'</nav>':'')+'<div class="toast" id="toast" style="display:none"></div></div></div>'}
function essentialHome(){const active=currentSession(),pause=state.breaks.find(b=>!b.ended_at),name=(state.profile?.full_name||state.user.email?.split('@')[0]||'').split(' ')[0];return '<div class="zen-home"><div class="zen-greeting"><span class="eyebrow">'+new Date().toLocaleDateString('fr-CA',{weekday:'long',day:'numeric',month:'long'})+'</span><h1>Bonjour'+(name?', '+e(name):'')+'.</h1><p>Une journée à votre rythme.</p></div><div class="zen-clock-card"><span class="zen-status"><span class="status-dot"></span>'+(pause?'En pause':active?'Votre journée est en cours':'Prêt pour votre journée ?')+'</span><strong class="zen-time" id="liveTimer">'+elapsed(essentialToday())+'</strong><span class="small muted">Temps travaillé aujourd’hui · pauses non payées exclues</span><button class="zen-punch '+(active?'finish':'')+'" data-action="punch" '+(state.busy?'disabled':'')+'>'+(active?'Terminer ma journée':'Commencer ma journée')+'<span>↗</span></button>'+(active?button(pause?'Reprendre le travail':'Prendre une pause non payée','pause','full zen-pause'):'<p class="zen-help">Un geste pour commencer. Un autre pour terminer.</p>')+'</div><div class="zen-summary"><div><span class="eyebrow">CETTE SEMAINE</span><strong id="weekTotal">'+mins(clockTotals().week)+'</strong></div><div><span class="eyebrow">STATUT</span><strong class="zen-small-status">'+(state.localPending?'Sauvegardé ici':'Synchronisé')+'</strong></div></div><div class="zen-company"><span class="zen-company-icon">▧</span><div><strong>'+e(state.account.companies.name)+'</strong><small>Votre espace de travail</small></div></div></div>'}

function essentialSchedule(){return heading('Horaire','more')+(manager()?card('<b>Planifier un quart</b><div class="group"><label>Personne</label><select id="shiftUser" class="field">'+state.members.map(m=>'<option value="'+e(m.user_id)+'">'+e(m.user_id.slice(0,8))+'</option>').join('')+'</select></div>'+jobSelect('shiftJob')+formfield('Début','shiftStart','','datetime-local')+formfield('Fin','shiftEnd','','datetime-local')+formfield('Note','shiftNote')+button('Planifier','scheduleShift','gold full')):'')+state.shifts.map(x=>card('<b>'+when(x.starts_at)+' → '+when(x.ends_at)+'</b><p class="muted">'+e(x.note||'Votre quart planifié')+'</p>'+(manager()?button('Annuler','cancelShift','',`data-id="${e(x.id)}"`):''))).join('');}

function essentialHours(){return heading('Mes heures')+card('<span class="eyebrow">CETTE SEMAINE</span><div class="zen-total">'+mins(clockTotals().week)+'</div>'+button('Exporter mes heures','exportHours','full'))+state.sessions.map(s=>card('<b>'+new Date(s.started_at).toLocaleDateString('fr-CA',{weekday:'long',day:'numeric',month:'short'})+'</b><p class="muted">'+when(s.started_at)+' → '+(s.ended_at?when(s.ended_at):'En cours')+'</p>')).join('')+button('Demander une correction','subpage','full','data-id="essentialCorrection"');}
function essentialMore(){const items=[['profile','Mon profil'],['leave','Mes congés'],...(manager()?[['approvals','Approbations et exports'],['geofence','Périmètre et punchs à valider'],['invitations','Inviter une personne']]:[]),['notifications','Notifications'],['settings','Paramètres']];return heading('Mon espace')+card('<b>'+e(state.account.companies.name)+'</b><p class="muted">PUNCH Essentiel</p>')+items.map(([id,title])=>'<button class="listitem" data-action="subpage" data-id="'+id+'"><span class="grow">'+title+'</span><span>›</span></button>').join('')+button('Se déconnecter','logout','full');}
function essentialApprovals(){return heading('Approbations','more')+geofenceReviewCard()+card('<b>Corrections en attente</b>'+state.corrections.filter(c=>c.status==='pending').map(c=>'<div class="group">'+e(c.reason)+button('Accepter','reviewCorrection','gold',`data-id="${e(c.id)}" data-approve="true"`)+button('Refuser','reviewCorrection','',`data-id="${e(c.id)}" data-approve="false"`)+'</div>').join(''))+card('<b>Congés en attente</b>'+state.leaves.filter(l=>l.status==='pending').map(l=>'<div class="group">'+e(l.begins_on)+' → '+e(l.ends_on)+button('Accepter','reviewLeave','gold',`data-id="${e(l.id)}" data-approve="true"`)+button('Refuser','reviewLeave','',`data-id="${e(l.id)}" data-approve="false"`)+'</div>').join(''))+card('<b>Fermer une semaine</b>'+formfield('Lundi de la semaine','payrollWeek','','date')+button('Fermer','closeWeek','gold')+button('Rouvrir','reopenWeek')+button('Exporter les heures','exportHours','full'));}
function essentialPage(){if(state.section==='home')return essentialHome();if(state.section==='hours')return essentialHours();if(state.section==='schedule')return schedulePage();if(state.section==='more')return essentialMore();if(state.section==='sub'){if(state.sub==='approvals')return essentialApprovals();if(state.sub==='essentialCorrection')return hoursPage();if(['profile','leave','geofence','invitations','notifications','settings','schedule'].includes(state.sub))return subPage();}return essentialHome();}
async function doPause(){if(state.busy||!currentSession())return;state.busy=true;try{await locatedPunch(state.breaks.some(b=>!b.ended_at)?'break_end':'break_start',null);await loadData();toast(state.localPending?'Pause conservée sur cet appareil':'Pause enregistrée')}catch(err){error(err)}finally{state.busy=false;draw()}}
function breakApprovals(){if(!manager())return '';return card('<b>Pauses hors ligne à valider</b>'+state.receipts.filter(r=>r.action?.startsWith('break_')&&r.result?.review_status==='pending').map(r=>'<div class="group">'+e(r.action==='break_start'?'Début de pause':'Fin de pause')+' · '+when(r.occurred_at)+button('Valider','reviewBreak','gold',`data-id="${e(r.event_id)}" data-worker="${e(r.user_id)}"`)+'</div>').join(''));}
async function reviewBreak(id,worker){const note=prompt('Motif de validation');if(!note)return;try{const r=await sb.rpc('review_break_event',{p_company:company(),p_worker:worker,p_event:id,p_note:note});if(r.error)throw r.error;await reload({quiet:true})}catch(err){error(err)}}

function renderMap(){if(state.section!=='jobs')return;const map=$('geoMap');if(!map)return;const list=jobList().filter(j=>j.latitude!=null&&j.longitude!=null);if(!list.length){map.innerHTML='<small>Aucune job avec coordonnées. L’admin peut ajouter une punaise GPS.</small>';return}map.innerHTML=list.slice(0,15).map((j,i)=>'<button style="left:'+((11+i*19)%80)+'%;top:'+((17+i*31)%67)+'%" data-action="detail" data-id="'+j.id+'" title="#'+e(j.number)+'">'+(i+1)+'</button>').join('')+'<small>Points indicatifs — utilise Google Maps/Waze pour la position réelle</small>'}
async function loadData(){if(!member())return;await punchJournal().flush();if(!navigator.onLine){const view=projectPendingPunches(state.serverPunch,await punchJournal().read());state.sessions=view.sessions;state.segments=view.segments;state.breaks=view.breaks;state.localPending=(await punchJournal().pending()).length;state.selected=view.segments.find(s=>!s.ended_at)?.job_id||view.lastJobId||state.selected;saveOfflineSnapshot();return;}const companyId=company();if(!companyId)return;try{
const calls=await Promise.all([
sb.from('jobs').select('id,company_id,number,name,address,latitude,longitude,punch_radius_m,photo_url,active').eq('company_id',companyId).eq('active',true).order('number'),
sb.from('job_assignments').select('job_id,planned_start').eq('company_id',companyId).eq('user_id',state.user.id).eq('active',true),
sb.from('punch_sessions').select('id,started_at,ended_at,user_id,company_id').eq('company_id',companyId).eq('user_id',state.user.id).order('started_at',{ascending:false}).limit(150),
sb.from('material_orders').select('id,created_at,created_by,job_id,status,note').eq('company_id',companyId).order('created_at',{ascending:false}).limit(100),
sb.from('leave_requests').select('id,user_id,leave_type,begins_on,ends_on,status,reason').eq('company_id',companyId).order('created_at',{ascending:false}).limit(100),
sb.from('punch_correction_requests').select('id,session_id,requested_by,requested_start,requested_end,reason,status,created_at,review_note').eq('company_id',companyId).order('created_at',{ascending:false}).limit(100),
sb.from('job_documents').select('id,name,kind,job_id,storage_path,requires_ack,version').eq('company_id',companyId),
sb.from('conversations').select('id,title,kind,team_id').eq('company_id',companyId),
sb.from('employee_profiles').select('full_name,phone').eq('user_id',state.user.id).maybeSingle(),
sb.from('emergency_contacts').select('id,priority,name,phone,relationship').eq('user_id',state.user.id),
sb.from('employee_credentials').select('id,credential_type,trade,expires_on').eq('user_id',state.user.id),
sb.from('teams').select('id,name,lead_user_id').eq('company_id',companyId),
sb.from('company_members').select('user_id,role').eq('company_id',companyId).eq('status','active'),
sb.from('punch_archive_preferences').select('segment_id').eq('user_id',state.user.id),
sb.from('payroll_weeks').select('*').eq('company_id',companyId).order('week_start',{ascending:false}),
sb.from('workforce_audit').select('id,action,reason,created_at').eq('company_id',companyId).order('created_at',{ascending:false}).limit(100),
sb.from('scheduled_shifts').select('*').eq('company_id',companyId).is('cancelled_at',null).order('starts_at'),
sb.from('document_acknowledgements').select('document_id,user_id').eq('user_id',state.user.id),
sb.from('punch_location_checks').select('*').eq('company_id',companyId).order('recorded_at',{ascending:false}).limit(200),
sb.from('app_notifications').select('*').eq('company_id',companyId).eq('recipient_id',state.user.id).order('created_at',{ascending:false}).limit(100),
sb.from('punch_event_receipts').select('event_id,user_id,action,job_id,occurred_at,offline,result').eq('company_id',companyId).order('received_at',{ascending:false}).limit(200),
sb.from('punch_breaks').select('id,company_id,user_id,session_id,started_at,ended_at').eq('company_id',companyId).eq('user_id',state.user.id)
]);const names=['jobs','assignments','sessions','orders','leaves','corrections','documents','conversations','profile','contacts','credentials','teamList','members','archived','weeks','audit','shifts','acks','locationChecks','notifications','receipts','breaks'];const errors=[];for(let i=0;i<calls.length;i++){if(calls[i].error)errors.push(names[i]+': '+calls[i].error.message);else state[names[i]]=names[i]==='profile'?calls[i].data||null:names[i]==='archived'?(calls[i].data||[]).map(a=>a.segment_id):calls[i].data||[]}
if(state.sessions.length){const ids=state.sessions.map(s=>s.id);const q=await sb.from('punch_segments').select('id,company_id,session_id,job_id,started_at,ended_at').eq('company_id',companyId).in('session_id',ids).order('started_at',{ascending:false}).limit(1800);if(q.error)errors.push('segments: '+q.error.message);else state.segments=q.data||[]}else state.segments=[];
if(!calls[2].error&&!errors.some(x=>x.startsWith('segments:')))state.serverPunch={sessions:state.sessions,segments:state.segments,breaks:state.breaks};const projected=projectPendingPunches(state.serverPunch,await punchJournal().read());state.sessions=projected.sessions;state.segments=projected.segments;state.breaks=projected.breaks;state.localPending=(await punchJournal().pending()).length;saveOfflineSnapshot();
const active=activeSegment();const preference=localStorage.getItem('punch360-selection-'+state.user.id);if(active&&getJob(active.job_id))state.selected=active.job_id;else if(!state.selected||!getJob(state.selected))state.selected=getJob(preference)?.id||state.segments.find(s=>getJob(s.job_id))?.job_id||state.jobs[0]?.id||null;
if(state.chatId&&!state.conversations.some(c=>c.id===state.chatId)){state.chatId=null;state.messages=[]}if(errors.length)toast('Quelques données non accessibles : '+errors[0]);
}catch(err){error(err)}}
async function reload({quiet=false}={}){if(state.busy)return;state.busy=true;if(!quiet)toast('Synchronisation…');try{await loadData();if(state.chatId)await loadChat(state.chatId)}catch(err){error(err)}finally{state.busy=false;draw();renderMap()}}
async function initialize(){try{const cached=JSON.parse(localStorage.getItem('punch-local-user')||'null');if(!navigator.onLine&&cached){state.user=cached;state.account=JSON.parse(localStorage.getItem('punch-account:'+cached.id)||'null');restoreOfflineSnapshot();if(member())await loadData();draw();return;}const {data,error:err}=await sb.auth.getSession();if(err&&!cached)throw err;state.user=data.session?.user||(err?cached:null);if(state.user)localStorage.setItem('punch-local-user',JSON.stringify({id:state.user.id,email:state.user.email}));restoreOfflineSnapshot();await lookupAccount();if(member())await loadData();draw();renderMap()}catch(err){state.error=err.message;draw();error(err)}}
async function lookupAccount(){state.account=null;if(!state.user)return;const q=await sb.from('company_members').select('company_id,role,companies(name,billing_status,product_edition,default_punch_job_id)').eq('user_id',state.user.id).eq('status','active').limit(1).maybeSingle();if(q.error){const cached=localStorage.getItem('punch-account:'+state.user.id);if(cached){state.account=JSON.parse(cached);return;}throw q.error;}if(q.data){let comp=q.data.companies;if(Array.isArray(comp))comp=comp[0];state.account={...q.data,companies:comp||{name:'Ma compagnie',billing_status:'setup'}};localStorage.setItem('punch-account:'+state.user.id,JSON.stringify(state.account));}else localStorage.removeItem('punch-account:'+state.user.id);}
function navigate(s){state.section=s;state.sub='';if(s==='messages')state.chatId=null;draw();renderMap()}
function detail(id){state.detailId=id;state.section='detail';state.showArchives=false;draw()}
function mapRoute(j,type){if(!j)return;window.open(urls[type](j),'_blank','noopener,noreferrer')}
async function requestGPS(){if(!navigator.geolocation){toast('GPS indisponible sur cet appareil');return}state.gpsLoading=true;navigator.geolocation.getCurrentPosition(p=>{state.position={latitude:p.coords.latitude,longitude:p.coords.longitude};state.gpsLoading=false;const nearest=state.jobs.filter(j=>j.latitude!=null&&j.longitude!=null).map(j=>({j,d:distance(state.position,j)})).sort((a,b)=>a.d-b.d)[0];if(!currentSession()&&nearest&&nearest.d<=0.5&&nearest.j.id!==state.selected&&confirm('Le GPS propose #'+nearest.j.number+' — '+nearest.j.name+'. Utiliser cette job pour le prochain PUNCH IN ?')){state.selected=nearest.j.id;localStorage.setItem('punch360-selection-'+state.user.id,state.selected)}draw();renderMap();toast('Position GPS disponible')},err=>{state.gpsLoading=false;toast('GPS non autorisé : '+err.message)}, {enableHighAccuracy:true,timeout:17000,maximumAge:20000})}
async function doPunch(){const j=selectedJob(),active=currentSession();if(!j||state.busy)return;if(!confirm((isEssential()?(active?'Terminer votre journée ?':'Commencer votre journée ?'):(active?'Confirmer PUNCH OUT ?':'Confirmer PUNCH IN sur #'+j.number+' — '+j.name+' ?'))+'\nHorodatage serveur.'))return;state.busy=true;try{const result=await locatedPunch(active?'out':'in',j.id);await loadData();toast(result.review_status==='local'?'Punch enregistré sur cet appareil — envoi au retour du réseau':result.review_status==='pending'?'Punch conservé — validation de l’administration requise':result.sync_status==='conflict'?'Conflit conservé et transmis à l’administration':'Punch enregistré — position dans le rayon');}catch(err){error(err)}finally{state.busy=false;draw()}}
async function selectJob(id){if(state.busy)return;const j=getJob(id);if(!j)return;if(currentSession()&&state.selected!==id){if(!confirm('Transférer les heures à #'+j.number+' sans interrompre le punch de la journée ?'))return;state.busy=true;try{await locatedPunch('transfer',id);await loadData();toast('Transfert de job enregistré')}catch(err){error(err)}finally{state.busy=false}}state.selected=id;localStorage.setItem('punch360-selection-'+state.user.id,id);navigate('home')}
async function submitCorrection(){const sid=$val('sessionCorrect'),reason=$val('correctionReason');if(!sid||reason.length<3)return toast('Choisis une journée et écris la raison.');try{const q=await sb.from('punch_correction_requests').insert({company_id:company(),session_id:sid,requested_by:state.user.id,reason,requested_start:$val('correctionStart')?new Date($val('correctionStart')).toISOString():null,requested_end:$val('correctionEnd')?new Date($val('correctionEnd')).toISOString():null});if(q.error)throw q.error;await reload({quiet:true});toast('Correction envoyée pour approbation')}catch(err){error(err)}}
async function createOrder(){const j=selectedJob(),note=$val('materialNote');if(!j||!note)return toast('Choisis une job et décris le matériel.');try{const r=await sb.from('material_orders').insert({company_id:company(),job_id:j.id,created_by:state.user.id,note});if(r.error)throw r.error;await reload({quiet:true});toast('Commande enregistrée sur Supabase')}catch(err){error(err)}}
async function archive(id){try{const archived=state.archived.includes(id);const q=archived?await sb.from('punch_archive_preferences').delete().eq('user_id',state.user.id).eq('segment_id',id):await sb.from('punch_archive_preferences').insert({user_id:state.user.id,segment_id:id});if(q.error)throw q.error;await reload({quiet:true});toast(archived?'Punch restauré':'Punch archivé sans supprimer ses heures')}catch(err){error(err)}}
async function createJob(){if(isRestrict())return toast('Gestion bloquée : abonnement à régulariser.');const number=$val('newJobNumber'),name=$val('newJobName'),address=$val('newJobAddress'),lat=$val('newJobLat'),lon=$val('newJobLon'),photo=$val('newJobPhoto');if(!number||!name)return toast('Numéro et nom obligatoires.');if((lat&&!lon)||(!lat&&lon))return toast('Fournis latitude et longitude ensemble.');try{const q=await sb.from('jobs').insert({company_id:company(),number,name,address,latitude:lat?Number(lat):null,longitude:lon?Number(lon):null,photo_url:photo||null});if(q.error)throw q.error;await reload({quiet:true});toast('Chantier créé');navigate('jobs')}catch(err){error(err)}}
async function saveProfile(){try{const r=await sb.from('employee_profiles').upsert({user_id:state.user.id,full_name:$val('profileName'),phone:$val('profilePhone')},{onConflict:'user_id'});if(r.error)throw r.error;await reload({quiet:true});toast('Profil enregistré')}catch(err){error(err)}}
async function saveContact(){const priority=Number($val('contactPriority'));if(!$val('contactName')||!$val('contactPhone'))return toast('Nom et téléphone obligatoires');try{const r=await sb.from('emergency_contacts').upsert({user_id:state.user.id,priority,name:$val('contactName'),phone:$val('contactPhone'),relationship:$val('contactRelationship')},{onConflict:'user_id,priority'});if(r.error)throw r.error;await reload({quiet:true});toast('Contact sauvegardé')}catch(err){error(err)}}
async function saveCredential(){const type=$val('certType');if(!type)return toast('Type de carte obligatoire');try{const r=await sb.from('employee_credentials').insert({user_id:state.user.id,credential_type:type,trade:$val('certTrade')||null,expires_on:$val('certExpiry')||null});if(r.error)throw r.error;await reload({quiet:true});toast('Certification enregistrée')}catch(err){error(err)}}
async function submitLeave(){const from=$val('leaveStart'),to=$val('leaveEnd');if(!from||!to||to<from)return toast('Dates invalides');try{const r=await sb.from('leave_requests').insert({company_id:company(),user_id:state.user.id,leave_type:$val('leaveType'),begins_on:from,ends_on:to,reason:$val('leaveReason')||null});if(r.error)throw r.error;await reload({quiet:true});toast('Congé soumis — en attente')}catch(err){error(err)}}
async function loadChat(id){const r=await sb.from('conversation_messages').select('id,body,sender_id,created_at').eq('conversation_id',id).order('created_at',{ascending:true}).limit(150);if(r.error)throw r.error;state.messages=r.data||[]}
async function sendMessage(){const body=$val('chatMessage');if(!body||!state.chatId)return;try{const r=await sb.from('conversation_messages').insert({company_id:company(),conversation_id:state.chatId,sender_id:state.user.id,body});if(r.error)throw r.error;await loadChat(state.chatId);draw();const c=$('main');if(c)c.scrollTop=c.scrollHeight}catch(err){error(err)}}
async function createGroup(){const title=$val('groupTitle');if(!title)return toast('Nom de groupe requis');const ids=[...document.querySelectorAll('.member-check:checked')].map(el=>el.value);try{const r=await sb.rpc('create_company_group',{p_company:company(),p_title:title,p_member_ids:ids});if(r.error)throw r.error;await loadData();state.chatId=r.data;state.section='messages';state.sub='';state.messages=[];draw();toast('Groupe créé')}catch(err){error(err)}}
async function privateChat(){const team=state.teamList.find(t=>t.lead_user_id===state.user.id);if(!team)return toast('Le boss doit affecter une équipe à ce chef.');try{const r=await sb.rpc('create_private_team_chat',{p_team:team.id});if(r.error)throw r.error;await loadData();state.chatId=r.data;state.messages=[];await loadChat(state.chatId);draw()}catch(err){error(err)}}
// Auth Google et Apple via la page Supabase; jamais de secret OAuth dans ce site public.
async function loadProviders(){
 try{
  const response=await fetch(PROJECT+'/auth/v1/settings',{headers:{apikey:PUBLISHABLE,Accept:'application/json'}});
  if(!response.ok)throw new Error('Provider discovery unavailable');
  const config=await response.json();
  if(typeof config.external?.google==='boolean')state.providers.google=config.external.google;
  if(typeof config.external?.apple==='boolean')state.providers.apple=config.external.apple;
  if(!member())draw();
 }catch(err){console.warn('OAuth provider status unavailable',err?.message||err)}
}
async function oauthLogin(provider){
 localStorage.setItem('punch-creation-edition',state.creationEdition);
 if(!['google','apple'].includes(provider)||state.busy)return;
 if(state.providers[provider]===false){
  toast((provider==='google'?'Google':'Apple')+' doit d’abord être activé dans Supabase → Authentication → Sign In / Providers.');
  return;
 }
 state.busy=true;
 try{
  const {error:loginError}=await sb.auth.signInWithOAuth({
   provider,
   options:{redirectTo:OAUTH_REDIRECT}
  });
  if(loginError)throw loginError;
  // Supabase redirige automatiquement ce navigateur vers Google ou Apple.
 }catch(err){error(err);state.busy=false}
}
function showOAuthCallbackError(){
 const fromQuery=new URLSearchParams(location.search);
 const fromHash=new URLSearchParams(location.hash.replace(/^#/,''));
 const code=fromQuery.get('error')||fromHash.get('error');
 if(!code)return;
 const detail=fromQuery.get('error_description')||fromHash.get('error_description')||code;
 history.replaceState(null,'',location.pathname);
 toast('Connexion refusée : '+detail);
}
async function login(mode){if(state.authBusy)return;const email=$val('email').toLowerCase(),password=$('password')?.value||'';if(!email||!$('email')?.checkValidity())return authMessage('Entre une adresse courriel valide.',true);if(!password||(mode==='signup'&&password.length<8))return authMessage(mode==='signup'?'Choisis un mot de passe d’au moins 8 caractères.':'Entre ton mot de passe.',true);state.authBusy=true;authMessage('');draw();try{const r=mode==='signup'?await sb.auth.signUp({email,password,options:{emailRedirectTo:OAUTH_REDIRECT}}):await sb.auth.signInWithPassword({email,password});if(r.error)throw r.error;if(!r.data.session){authMessage('Vérifie ta boîte courriel et les indésirables pour confirmer ton inscription. Reviens ensuite te connecter. Si ce courriel est déjà inscrit, utilise « Mot de passe oublié ».');}else{if($('password'))$('password').value='';await initialize()}}catch(err){authFailure(err)}finally{state.authBusy=false;draw()}}
async function resetPassword(){if(state.authBusy)return;const email=$val('email').toLowerCase();if(!email||!$('email')?.checkValidity())return authMessage('Entre ton adresse courriel pour recevoir le lien.',true);state.authBusy=true;try{const r=await sb.auth.resetPasswordForEmail(email,{redirectTo:OAUTH_REDIRECT});if(r.error)throw r.error;authMessage('Si ce compte existe, un lien de récupération sera envoyé. Vérifie aussi les indésirables.')}catch(err){authFailure(err)}finally{state.authBusy=false}}
async function resendConfirmation(){if(state.authBusy)return;const email=$val('email').toLowerCase();if(!email||!$('email')?.checkValidity())return authMessage('Entre une adresse courriel valide.',true);state.authBusy=true;try{const r=await sb.auth.resend({type:'signup',email,options:{emailRedirectTo:OAUTH_REDIRECT}});if(r.error)throw r.error;authMessage('Lien de confirmation demandé. Vérifie ta boîte courriel et les indésirables.')}catch(err){authFailure(err)}finally{state.authBusy=false}}
async function savePassword(){if(state.authBusy)return;const password=$('newPassword')?.value||'';if(password.length<8)return authMessage('Choisis un mot de passe d’au moins 8 caractères.',true);if(password!==$('confirmPassword')?.value)return authMessage('Les mots de passe ne correspondent pas.',true);state.authBusy=true;try{const r=await sb.auth.updateUser({password});if(r.error)throw r.error;state.recovery=false;authMessage('Mot de passe enregistré.');await initialize()}catch(err){authFailure(err)}finally{state.authBusy=false;draw()}}
async function createCompany(){if(state.authBusy)return;const n=$val('companyName');if(n.length<2)return authMessage('Entre le nom de ton entreprise (au moins 2 caractères).',true);state.authBusy=true;draw();try{const r=await sb.rpc('create_company_for_edition',{p_name:n,p_edition:state.creationEdition});if(r.error)throw r.error;await initialize();toast('Ton espace PUNCH est prêt')}catch(err){authFailure(err)}finally{state.authBusy=false;draw()}}

async function logOut(){localStorage.removeItem('punch-local-user');await sb.auth.signOut();state.user=null;state.account=null;state.section='home';state.chatId=null;draw()}
function tick(){state.time=Date.now();const t=$('liveTimer'),cs=currentSession();if(t)t.textContent=isEssential()?elapsed(essentialToday()):elapsed(cs?state.time-Date.parse(cs.started_at):0);const w=$('weekTotal'),y=$('yearTotal');if(w||y){const tot=clockTotals();if(w)w.textContent=mins(tot.week);if(y)y.textContent=mins(tot.year)}if($('topclock'))$('topclock').textContent=new Date().toLocaleTimeString('fr-CA',{hour:'2-digit',minute:'2-digit'})}
document.addEventListener('click',async ev=>{const el=ev.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;try{
if(a==='navigate')navigate(id);
else if(a==='home'||a==='jobs'||a==='messages')navigate(a);
else if(a==='profile'){state.section='sub';state.sub='profile';draw()}
else if(a==='refresh')await reload();
else if(a==='openJobs'||a==='switchJobs'){state.routeMode=a==='switchJobs'?'switch':'browse';navigate('jobs')}
else if(a==='detail')detail(id);
else if(a==='openDetail'){const j=selectedJob();if(j)detail(j.id)}
else if(a==='hoursDetail'){const seg=state.segments.find(x=>x.session_id===id);if(seg)detail(seg.job_id)}
else if(a==='orderPage')navigate('orders');
else if(a==='filter'){state.filter=id;if(id==='near'&&!state.position)await requestGPS();draw();renderMap()}
else if(a==='gps')await requestGPS();
else if(a==='punch')await doPunch();
else if(a==='selectDetail')await selectJob(state.detailId);
else if(a==='maps'){ev.stopPropagation();mapRoute(getJob(id),'google')}
else if(a==='waze'||a==='googleMaps')mapRoute(getJob(state.detailId),a==='waze'?'waze':'google');
else if(a==='archiveToggle'){state.showArchives=!state.showArchives;draw()}
else if(a.startsWith('archive:'))await archive(a.split(':')[1]);
else if(a==='login'||a==='signup')await login(a);
else if(a==='authMode'){state.authMode=state.authMode==='login'?'signup':'login';authMessage('');draw()}
else if(a==='resendConfirmation')await resendConfirmation();
else if(a==='oauthGoogle')await oauthLogin('google');
else if(a==='oauthApple')await oauthLogin('apple');
else if(a==='logout')await logOut();
else if(a==='resetPassword')await resetPassword();
else if(a==='createCompany')await createCompany();
else if(a==='chooseEdition'){state.creationEdition=id;localStorage.setItem('punch-creation-edition',id);const url=new URL(location.href);url.searchParams.set('edition',id);history.replaceState(null,'',url);draw()}
else if(a==='pause')await doPause();
else if(a==='reviewBreak')await reviewBreak(id,el.dataset.worker);
else if(a==='reviewCorrection')await reviewRecord('review_punch_correction',id,el.dataset.approve==='true');
else if(a==='reviewLeave')await reviewRecord('review_leave',id,el.dataset.approve==='true');
else if(a==='advanceOrder')await advanceOrder(id,el.dataset.status);
else if(a==='saveGeofence')await saveGeofence(id);
else if(a==='reviewLocation'||a==='correctLocation')await reviewLocation(id,a==='correctLocation');
else if(a==='readNotification')await readNotification(id);
else if(a==='scheduleShift')await scheduleShift();
else if(a==='cancelShift')await cancelShift(id);
else if(a==='createInvitation')await createInvitation();
else if(a==='acceptInvitation')await acceptInvitation();
else if(a==='uploadDocument')await uploadDocument();
else if(a==='openDocument')await openDocument(id);
else if(a==='ackDocument')await ackDocument(id);
else if(a==='closeWeek'||a==='reopenWeek')await setWeek(a==='closeWeek');
else if(a==='exportHours')await exportHours();
else if(a==='correction')await submitCorrection();
else if(a==='submitOrder')await createOrder();
else if(a==='subpage'){state.section='sub';state.sub=id;draw()}
else if(a==='createJob')await createJob();
else if(a==='saveProfile')await saveProfile();
else if(a==='saveContact')await saveContact();
else if(a==='saveCredential')await saveCredential();
else if(a==='submitLeave')await submitLeave();
else if(a==='chat'){state.chatId=id;state.messages=[];await loadChat(id);draw()}
else if(a==='sendMessage')await sendMessage();
else if(a==='newGroup'){state.section='sub';state.sub='group';draw()}
else if(a==='createGroup')await createGroup();
else if(a==='privateChat')await privateChat();
}catch(err){error(err)}});
document.addEventListener('submit',ev=>{if(ev.target?.id==='recoveryForm'){ev.preventDefault();savePassword();return}if(ev.target?.id==='authForm'){ev.preventDefault();login(state.authMode)}});
document.addEventListener('input',ev=>{if(ev.target?.id==='jobSearch'){state.search=ev.target.value;const current=ev.target.selectionStart;const newHtml=jobsPage();const m=$('main');if(m){const y=m.scrollTop;m.innerHTML=newHtml;m.scrollTop=y;const inp=$('jobSearch');inp?.focus();try{inp?.setSelectionRange(current,current)}catch{}}renderMap()}});
sb.auth.onAuthStateChange((event,session)=>{if(event==='PASSWORD_RECOVERY'){state.recovery=true;setTimeout(draw,0)}else if(event==='SIGNED_OUT'){localStorage.removeItem('punch-local-user');state.user=null;state.account=null;state.section='home';draw()}else if(event==='SIGNED_IN'){setTimeout(initialize,0)}});
initialize().then(()=>showOAuthCallbackError());loadProviders();setInterval(tick,1000);setInterval(async()=>{if(state.chatId&&member()&&!state.busy){try{await loadChat(state.chatId);if(state.section==='messages')draw()}catch{}}},10000);

if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(console.warn);
